def light_cargo(weights, values, cap):
    top = sum(values)
    lightest = [0] + [cap + 1] * top      # cap + 1 stands for "cannot be made within cap"
    for w, v in zip(weights, values):
        if w > cap:
            continue
        for t in range(top, v - 1, -1):
            load = lightest[t - v] + w
            if load < lightest[t]:
                lightest[t] = load
    return max(t for t in range(top + 1) if lightest[t] <= cap)

