def light_cargo(weights, values, cap):
    order = sorted(range(len(weights)), key=lambda i: values[i] / weights[i], reverse=True)
    load = total = 0
    for i in order:
        if load + weights[i] <= cap:
            load += weights[i]
            total += values[i]
    return total

def light_cargo(weights, values, cap):
    top = sum(values)
    lightest = [0] + [float('inf')] * top
    for w, v in zip(weights, values):
        for t in range(top, v - 1, -1):
            lightest[t] = min(lightest[t], lightest[t - v] + w)
    return max(t for t in range(top + 1) if lightest[t] < cap)

