def light_cargo(weights, values, cap):
    best = [0] * (cap + 1)
    for w, v in zip(weights, values):
        for t in range(cap, w - 1, -1):
            if best[t - w] + v > best[t]:
                best[t] = best[t - w] + v
    return best[cap]
